// Finds a company's products: the folders the company file lists, each with
// its product.json next to the code; or, in a factory from before 0.6.0
// (no list), each folder in the factory folder's products/ with one. The
// factory knows a product only from there, never by its name in code.
import { existsSync, globSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { COMPANY_FILE, readCompany } from "../company/company.js";
import { readProduct } from "./product.js";
export const PRODUCT_FILE = "product.json";
// Where a factory from before 0.6.0 described its products.
export const PRODUCTS_FOLDER = "products";
// The products of the factory at root, and what is wrong with the ones that
// could not be read.
export function findProducts(root) {
    const read = readCompany(join(root, COMPANY_FILE));
    const listed = "company" in read ? read.company.products : undefined;
    return listed ? productsListed(dirname(root), listed) : productsInside(root);
}
// The products in the folders the company file lists.
function productsListed(project, folders) {
    const products = [];
    const problems = [];
    for (const folder of folders) {
        const file = join(resolve(project, folder), PRODUCT_FILE);
        if (!existsSync(file)) {
            problems.push(`${folder}: there is no ${PRODUCT_FILE} in it`);
            continue;
        }
        const found = readProduct(file);
        if ("problem" in found)
            problems.push(found.problem);
        else
            products.push(found.product);
    }
    return { products, problems };
}
// The products described in the factory folder's products/ (before 0.6.0).
function productsInside(root) {
    const files = globSync(join(PRODUCTS_FOLDER, "*", PRODUCT_FILE), {
        cwd: root,
    }).sort((a, b) => a.localeCompare(b));
    const products = [];
    const problems = [];
    for (const file of files) {
        const read = readProduct(join(root, file));
        const folder = file.split(/[\\/]/)[1];
        if ("problem" in read)
            problems.push(read.problem);
        else if (read.product.id !== folder)
            problems.push(`${file}: its id is "${read.product.id}", but its folder is "${folder ?? ""}"`);
        else
            products.push(read.product);
    }
    return { products, problems };
}
